# System.Runtime.Intrinsics.X86.Avx512BW — word shifts, with avx512f/bitwise.map's conventions:
# a count at or above 16 saturates (zero, or the sign fill), every byte immediate is valid and
# the references spell the saturation; the register-count forms read the low 64 bits of the
# count operand; the Variable forms saturate lane by lane. The 128-bit-lane forms shift whole
# bytes within each lane; 16 or more gives zero.
target = avx512f,avx512bw,avx512dq,avx512vl
ShiftLeftLogical(v512{T},u8) @imm8 @ref($1 < 16 ? Vector512.ShiftLeft($0, $1) : Vector512<{cs}>.Zero) = _mm512_slli_epi16($0, $1) for T in i16,u16
ShiftLeftLogical(v512{T},v128{T}) @ref($1.AsUInt64().GetElement(0) < 16 ? Vector512.ShiftLeft($0, (int)$1.AsUInt64().GetElement(0)) : Vector512<{cs}>.Zero) = _mm512_sll_epi16($0, $1) for T in i16,u16
ShiftLeftLogicalVariable(v512{T},v512u16) = _mm512_sllv_epi16($0, $1) for T in i16,u16
ShiftRightLogical(v512{T},u8) @imm8 @ref($1 < 16 ? Vector512.ShiftRightLogical($0, $1) : Vector512<{cs}>.Zero) = _mm512_srli_epi16($0, $1) for T in i16,u16
ShiftRightLogical(v512{T},v128{T}) @ref($1.AsUInt64().GetElement(0) < 16 ? Vector512.ShiftRightLogical($0, (int)$1.AsUInt64().GetElement(0)) : Vector512<{cs}>.Zero) = _mm512_srl_epi16($0, $1) for T in i16,u16
ShiftRightLogicalVariable(v512{T},v512u16) = _mm512_srlv_epi16($0, $1) for T in i16,u16
ShiftRightArithmetic(v512i16,u8) @imm8 @ref(Vector512.ShiftRightArithmetic($0, Math.Min((int)$1, 15))) = _mm512_srai_epi16($0, $1)
ShiftRightArithmetic(v512i16,v128i16) @ref(Vector512.ShiftRightArithmetic($0, (int)Math.Min($1.AsUInt64().GetElement(0), 15UL))) = _mm512_sra_epi16($0, $1)
ShiftRightArithmeticVariable(v512i16,v512u16) = _mm512_srav_epi16($0, $1)
ShiftLeftLogical128BitLane(v512{T},u8) @imm8 = _mm512_bslli_epi128($0, $1) for T in i8,u8
ShiftRightLogical128BitLane(v512{T},u8) @imm8 = _mm512_bsrli_epi128($0, $1) for T in i8,u8
